import React, { useState, useEffect } from "react";
import { motion } from "framer-motion";
import { Sparkles, Clock } from "lucide-react";

const FESTIVALS = [
  { name: "Diwali", date: new Date("2025-11-01"), emoji: "🪔" },
  { name: "Wedding Season", date: new Date("2025-11-15"), emoji: "💒" },
  { name: "Christmas", date: new Date("2025-12-25"), emoji: "🎄" },
  { name: "New Year", date: new Date("2026-01-01"), emoji: "🎆" },
  { name: "Vasant Panchami", date: new Date("2026-01-14"), emoji: "🌼" },
  { name: "Holi", date: new Date("2026-03-14"), emoji: "🎨" },
];

function getNextFestival() {
  const now = new Date();
  for (const festival of FESTIVALS) {
    if (festival.date > now) {
      return festival;
    }
  }
  // If all passed, return next year's Diwali
  return { name: "Diwali 2026", date: new Date("2026-10-20"), emoji: "🪔" };
}

function calculateTimeLeft(targetDate) {
  const difference = targetDate - new Date();
  if (difference <= 0) return null;

  return {
    days: Math.floor(difference / (1000 * 60 * 60 * 24)),
    hours: Math.floor((difference / (1000 * 60 * 60)) % 24),
    minutes: Math.floor((difference / 1000 / 60) % 60),
    seconds: Math.floor((difference / 1000) % 60),
  };
}

export default function CountdownTimer() {
  const [timeLeft, setTimeLeft] = useState(null);
  const [festival, setFestival] = useState(getNextFestival());

  useEffect(() => {
    const updateTimer = () => {
      const newFestival = getNextFestival();
      if (newFestival.name !== festival.name) {
        setFestival(newFestival);
      }
      setTimeLeft(calculateTimeLeft(newFestival.date));
    };

    updateTimer();
    const timer = setInterval(updateTimer, 1000);
    return () => clearInterval(timer);
  }, [festival.name]);

  if (!timeLeft) return null;

  return (
    <motion.div
      initial={{ opacity: 0, y: 20 }}
      whileInView={{ opacity: 1, y: 0 }}
      viewport={{ once: true }}
      transition={{ duration: 0.6 }}
      className="w-full py-12 md:py-16"
      style={{ background: "linear-gradient(135deg, #1a080a 0%, #2d1118 100%)" }}
    >
      <div className="px-6 md:px-12 lg:px-24 max-w-6xl mx-auto">
        {/* Header */}
        <div className="text-center mb-8">
          <div className="inline-flex items-center gap-2 px-4 py-2 rounded-full mb-4" style={{ background: "rgba(212,175,55,0.15)", border: "1px solid rgba(212,175,55,0.3)" }}>
            <Sparkles size={16} color="#d4af37" />
            <span className="text-xs tracking-[0.2em] uppercase font-semibold" style={{ color: "#d4af37" }}>
              Book Early, Save Big
            </span>
          </div>
          <h2 className="serif text-2xl md:text-4xl mb-3" style={{ color: "#ffffff" }}>
            <span className="mr-2">{festival.emoji}</span>
            {festival.name} Sale
            <span className="ml-2">{festival.emoji}</span>
          </h2>
          <p className="text-sm md:text-base" style={{ color: "rgba(255,255,255,0.7)" }}>
            Special bulk pricing for orders placed before the season
          </p>
        </div>

        {/* Countdown */}
        <div className="flex flex-wrap justify-center gap-4 md:gap-6 mb-8">
          {[
            { value: timeLeft.days, label: "Days" },
            { value: timeLeft.hours, label: "Hours" },
            { value: timeLeft.minutes, label: "Minutes" },
            { value: timeLeft.seconds, label: "Seconds" },
          ].map((item, i) => (
            <motion.div
              key={item.label}
              initial={{ scale: 0.8, opacity: 0 }}
              animate={{ scale: 1, opacity: 1 }}
              transition={{ delay: i * 0.1, duration: 0.4 }}
              className="text-center"
            >
              <div
                className="w-16 h-16 md:w-20 md:h-20 rounded-xl flex items-center justify-center mb-2"
                style={{
                  background: "linear-gradient(135deg, rgba(212,175,55,0.2), rgba(212,175,55,0.05))",
                  border: "1px solid rgba(212,175,55,0.4)",
                  boxShadow: "0 8px 32px rgba(212,175,55,0.2)",
                }}
              >
                <span className="text-2xl md:text-3xl font-bold" style={{ color: "#d4af37" }}>
                  {String(item.value).padStart(2, "0")}
                </span>
              </div>
              <span className="text-xs uppercase tracking-wider" style={{ color: "rgba(255,255,255,0.5)" }}>
                {item.label}
              </span>
            </motion.div>
          ))}
        </div>

        {/* CTA */}
        <div className="flex flex-wrap justify-center gap-4">
          <a
            href="#contact"
            className="inline-flex items-center gap-2 px-6 py-3 rounded-full font-semibold transition-all hover:scale-105"
            style={{
              background: "linear-gradient(135deg, #d4af37, #f4d77a)",
              color: "#1a080a",
              boxShadow: "0 8px 32px rgba(212,175,55,0.4)",
            }}
          >
            <Clock size={18} />
            Book Your Order Now
          </a>
          <a
            href="https://wa.me/919888919983?text=Hi!%20I'm%20interested%20in%20the%20upcoming%20season%20sale"
            target="_blank"
            rel="noopener noreferrer"
            className="inline-flex items-center gap-2 px-6 py-3 rounded-full font-semibold transition-all hover:scale-105"
            style={{
              background: "transparent",
              color: "#ffffff",
              border: "2px solid rgba(212,175,55,0.5)",
            }}
          >
            Chat on WhatsApp
          </a>
        </div>

        {/* Urgency Text */}
        <p className="text-center mt-6 text-sm" style={{ color: "rgba(255,255,255,0.5)" }}>
          <span className="text-[#d4af37]">Limited time offer</span> • Free shipping on orders above ₹50,000
        </p>
      </div>
    </motion.div>
  );
}
